				System.out.println("1");
				continue;
			}
			int ans = 0;
			for (int i = 0; i < 2 * N; ++i) {
				for (int j = 0; j < 2 * N; ++j) {
					if (i % N == j % N)
						continue;
					double theta = (x[i] == x[j] ? 0 : Math.atan((y[j] - y[i]) / (x[j] - x[i])));
					double w = Math.sqrt((x[j] - x[i]) * (x[j] - x[i]) + (y[j] - y[i]) * (y[j] - y[i]));
