		int r = 0;
		char c = 'A';
		for(int i = 0; i < s.length(); i++){
			if(s.charAt(i) == '['){
				int k = i+1, rank = 1;
				while(rank>0){
					if(i+k>=s.length()) break;
					if(s.charAt(i+k)=='[') rank++;
					else if(s.charAt(i+k)==']') rank--;
					k++;
				}
				//System.out.println("OK");
				ret.append(calc(s.substring(i + 1, Math.min(i + k, s.length())), true));
