				if (A[i] == B[j]) {
					dp[j + 1] = Math.max(dp[j + 1], dp[j] + 1);
				}
			}
		}
		int ans = 0;
		for (int i = 1; i <= M; ++i) {
			ans = Math.max(ans, dp[i]);
		}
		System.out.println(ans);
	}
}

