		dir[BACK] = 7 - front;
		dir[RIGHT] = right[up - 1][front - 1];
		dir[LEFT] = 7 - dir[RIGHT];
		boolean bRoll = false;
		if(high > 0){
			for(int i = 6; i >= 4; i--){
				for(int j = 0; j < 4; j++){
					if(dir[j] == i){
						int xx = x,yy = y;
