    static class TaskD {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            long a = in.nextLong();
            long b = in.nextLong();
            int[] p = new int[n];
            for (int i = 0; i < n; ++i) {
                p[i] = in.nextInt();
            }
            long[] best = new long[n + 2];
            for (int i = 0; i < n + 1; ++i) {
                best[i + 1] = Long.MAX_VALUE;
                long extra = 0;
                for (int j = i - 1; j >= -1; --j) {
                    if (i == n || j < 0 || p[j] < p[i]) {
                        best[i + 1] = Math.min(best[i + 1], best[j + 1] + extra);
                    }
                    if (j >= 0) {
                        if (i == n || p[j] < p[i]) {
                            extra += b;
                        } else {
                            extra += a;
                        }
                    }
                }
            }
            out.println(best[n + 1]);
        }

