		for (int i = 0; i < n; i++) {
			int p = scanInt();
			long c = Long.MAX_VALUE;
			for (int j = 0; j < p; j++) {
				c = min(c, dyn[j]);
				dyn[j] += a;
			}
			dyn[p] = c;
			for (int j = p + 1; j <= n; j++) {
				dyn[j] += b;
			}
		}
		long ans = Long.MAX_VALUE;
		for (int i = 0; i <= n; i++) {
