	static void write(int key, int count) {
		if (key == 0) {
			for (int i = 0; i < count - 1; ++i) {
				System.out.print(' ');
			}
		} else {
			--count;
			System.out.print(table[key].charAt(count % table[key].length()));
		}
	}

}

