class Node:
    def __init__(self, value):
        self.value = value
        self.next = None


class List:
    def __init__(self):
        self.head = None
        self.tail = None

    def insert(self, v):
        node = Node(v)
        if self.tail is None:
            self.head = node
            self.tail = node
        else:
            self.tail.next = node
            self.tail = node

    def dump(self):
        node = self.head
        while node is not None:
            yield node.value
            node = node.next

    def splice(self, li):
        if self.head is None:
            self.head = li.head
            self.tail = li.tail
        else:
            self.tail.next = li.head
            self.tail = li.tail
        li.clear()

