    }

    static long comb(long n, long k, long[] fact, long[] ifact){
        if(n < k) return 0;
        if(n <= 0 || k <= 0 || n-k == 0) return 1;
        return (((fact[(int)n-1] * ifact[(int)n-(int)k-1])%DIV) * ifact[(int)k-1])%DIV;
    }

    public static long inverseElement(long a, long n){
        long b = n, u=1, v=0;
        while(b > 0) {
            long t = a/b;
            a -= t*b;
            u -= t*v;
            //swap
            t = a;
            a = b;
            b = t;
            t = u;
            u = v;
            v = t;
        }
        u = u % n;
        if(u < 0) u += n;
        return u;
    }
}

