    	while(true){
    		final int N = sc.nextInt();

    		if(N == 0){
    			break;
    		}

    		LinkedList<File> files = new LinkedList<File>();

    		for(int i = 0; i < N; i++){
    			String ops = sc.next();

    			//System.out.println(files);

    			if("W".equals(ops)){
    				final int l = sc.nextInt();
