		return new Vector2d(v2.x - v1.x, v2.y - v1.y);
	}

	public static int solve(List<Vector2d> p) {
		boolean ans = true;
		int s = p.size();
		for (int i=0; i<s; i++) {
			Vector2d a = sub(p.get(i), p.get((i+1)%s));
			Vector2d b = sub(p.get((i+1)%s), p.get((i+2)%s));
			ans = ans && ((a.x * b.y - a.y * b.x) >= 0);
		}
		return ans ? 1 : 0;
	}
