    public static long[][] initWF(int N) {
        long[][] D = new long[N][N];
        for (int i = 0; i < N; i++) {
            for (int j = 0; j < N; j++) {
                if (i != j) {
                    D[i][j] = Long.MAX_VALUE;
                }
            }
        }
        return D;
    }

    public static void execWF(int N, long[][] D) {
        for (int k = 0; k < N; k++) {
            for (int i = 0; i < N; i++) {
                for (int j = 0; j < N; j++) {
                    if (D[i][k] != Long.MAX_VALUE && D[k][j] != Long.MAX_VALUE) {
                        D[i][j] = Math.min(D[i][j], D[i][k] + D[k][j]);
                    }
                }
            }
        }
    }

