def line_segment_circle(x0, y0, x1, y1, r, border=True):
    A = x0**2 + y0**2
    B = x0*x1 + y0*y1
    C = x1**2 + y1**2 - r**2
    D = B**2 - A*C
    if border:
        if D < 0:
            return 0
        if B <= 0 and B**2 > D:
            return 0
        if B - A >= 0 and (B - A)**2 > D:
            return 0
    else:
        if D <= 0:
            return 0
        if B <= 0 and B**2 >= D:
            return 0
        if B - A >= 0 and (B - A)**2 >= D:
            return 0
    return 1

