public class Main{

	int n, MOD = 10007;
	int[][] e, f;
	boolean[] v;

	int bfs(int s){
		v[s] = true;
		int max = -1, c = 0;
		Queue<Integer> q = new LinkedList<Integer>();
		q.add(s);
		while(!q.isEmpty()){
			int p = q.poll();
			for(int i=0;i<2;i++){
				if(max<f[p][i]){
					max = f[p][i]; c = 1;
				}
				else if(max==f[p][i])c++;
				if(!v[e[p][i]]){
					v[e[p][i]] = true; q.add(e[p][i]);
				}
			}
		}
		return (c/2)%MOD;
	}

