			boolean [][] iserase = new boolean[h][w];

			for(int i = 0; i < w; i++){
				int ind = h-1;
				for(int j = h-1; j >= 0; j--){
					if(work[j][i] != '.'){
						work[ind][i] = work[j][i];
						ind--;
					}
				}
				for(; ind >= 0; ind--){
					work[ind][i] = '.';
				}
			}

			for(int i = 0; i < h; i++){
				for(int j = 0; j < w; j++){
					if(work[i][j] == '.') continue;
					int count = 0;
					for(int k = j; k < w; k++){
						if(work[i][j] == work[i][k]){
							count++;
						}
						else{
							break;
						}
					}
					if(count >= n){
						for(int k = j; k < w; k++){
