			System.out.println(octs.size());
		}
	}

	static void dfs(int pos, int[] color, boolean[] used) {
		if (pos == 8) {
			if (check(color)) {
				octs.add(new Oct(color));
			}
			return;
		}
		for (int i = 1; i < 8; ++i) {
			if (used[i]) continue;
			color[pos] = C[i];
			used[i] = true;
			dfs(pos + 1, color, used);
			used[i] = false;
		}
	}

	static boolean check(int[] color) {
		int[] c = new int[8];
		for (int i = 0; i < 6; ++i) {
