						return false;
					}
				}
			}
		}
		return true;
	}

	static void rot(int[] color) {
		for (int i = 0; i < 2; ++i) {
			int tmp = color[i * 4 + 0];
			color[i * 4 + 0] = color[i * 4 + 1];
			color[i * 4 + 1] = color[i * 4 + 2];
			color[i * 4 + 2] = color[i * 4 + 3];
			color[i * 4 + 3] = tmp;
		}
	} 

