		}
		maxT=sc.nextInt();
		solve();
	}

	void solve(){
		visited=new boolean[m][m];
		long[] dp=new long[maxT+1];
		for(int j=0; j<n; j++){
			int num=0;
			for(int y=0; y<m; y++){
				for(int x=0; x<m; x++){
					num+=dfs(x, y, words[j], 0);
				}
			}
			int weight=words[j].length(), value=scores[j];
			for(int k=1; num>0; k<<=1){
				int mul=min(k, num);
				for(int i=maxT; i-weight*mul>=0; i--){
					dp[i]=max(dp[i], dp[i-weight*mul]+value*mul);
				}
				num-=mul;
			}
		}
		println(dp[maxT]+"");
	}

