    sx,sy,f = xyf
    x=int(sx)
    y=int(sy)
    if f == 'S':
        s = raySW(x,y)
        t = w - raySW(w-x,y)  # flip in X
        return (s,t)
    if f == 'E':
        s = w - raySW(w-x,y)  # flip in X
        t = w + d + raySW(w-x,d-y) # flip in both X and Y
        return (s,t)
    if f == 'N':
        s = w + d + raySW(w-x,d-y) # flip in both X and Y
        t = w + d + w - raySW(x,d-y)  # flip in Y
        return (s,t)
    if f == 'W':
        s = w + d + w - raySW(x,d-y)  # flip in Y
        t = w + d + w + d + raySW(x,y)
