			switch (scan.next()) {
			case "N":
				ary[i][0] = w + (w - x + y);
				ary[i][1] = ary[i][0] + (d - y) * 2;
				break;
			case "E":
				ary[i][0] = x + y;
				ary[i][1] = ary[i][0] + (w - x) * 2;
				break;
			case "S":
				if (x < y)
					ary[i][0] = 2 * w + 2 * d - (y - x);
				else
					ary[i][0] = x - y;
				ary[i][1] = ary[i][0] + y * 2;
				break;
			default:
				ary[i][0] = w + d + (w - x) + (d - y);
				ary[i][1] = ary[i][0] + x * 2;
