			c[i][0] = 1;
			for(int j = 1; j <= i; j++) {
				c[i][j] = c[i - 1][j - 1] + c[i - 1][j];
				c[i][j] %= mod;
			}
		}
		ArrayList <Integer> chain = new ArrayList <> ();
		for(int i = 1; i <= k; i++) {
			int sz = 0;
			int cur = i;
			while(cur <= n) {
				++sz;
				cur += k;
			}
			chain.add(sz);
			chain.add(sz);
		}
		dp[0][0] = 1;
		int row = 0;
		for(int i = 1; i <= chain.size(); i++) {
			int sz = chain.get(i - 1);
			row ^= 1;
			for(int j = 0; j <= n; j++) {
				dp[row][j] = 0;
				for(int x = 0; x <= Math.min(j, sz); x++) {
					dp[row][j] += dp[row ^ 1][j - x] * c[sz - x][x];
					dp[row][j] %= mod;
				}
			}
		}

		long ans = 0;
		for(int i = 0; i <= n; i++) {
			if(i % 2 == 1) {
				ans -= fac[n - i] * dp[row][i];
			} else {
				ans += fac[n - i] * dp[row][i];
			}
			ans %= mod;
		}
		if(ans < 0) ans += mod;
		System.out.println(ans);
	}
