public class Main {

	Scanner sc = new Scanner(in);

	class Point {
		int x, y;
		int t;
		int ig;
		Point(int x, int y, int t, int ig) {
			this.x =x;
			this.y = y;
			this.t = t;
			this.ig = ig;
		}
		@Override
		public boolean equals(Object obj) {
			if (obj == null || !(obj instanceof Point)) return false;
			return ((Point)obj).x == this.x && ((Point)obj).y == this.y && ((Point)obj).t == this.t && ((Point)obj).ig == this.ig;
		}
	}

	class MyComparator<T> implements Comparator<T> {
		@Override
		public int compare(T o0, T o1) {
			return ((Point)o0).ig-((Point)o1).ig;
		}
	}

	void run() {
		int INF = 1000000000;
		int pad = 101;
		int sx = sc.nextInt(), sy = sc.nextInt(), gx = sc.nextInt(), gy = sc.nextInt();
		int n = sc.nextInt();
		boolean[][] map = new boolean[2*pad][2*pad];
		for (int i = 0; i < n; i++) {
			map[sc.nextInt()+pad][sc.nextInt()+pad] = true;
		}
		int lx = sc.nextInt(), ly = sc.nextInt();
		int[][][] cost = new int[2*pad][2*pad][6];
		for (int x = -lx; x <= lx; x++)
			for (int y = -ly; y <= ly; y++)
				for (int t = 0; t < 6; t++)
					cost[x+pad][y+pad][t] = INF;
		cost[sx+pad][sy+pad][0] = 0;

		PriorityQueue<Point> queue = new PriorityQueue<Point>(11,new MyComparator<Point>());
		queue.add(new Point(sx, sy, 0, 0));

		int[] x0 = {0,1, 1, 0,-1,-1,0};
		int[] y0 = {1,0,-1,-1,-1, 0,0};
		int[] x1 = {0,1,1, 0,-1,-1,0};
		int[] y1 = {1,1,0,-1, 0, 1,0};

		while (!queue.isEmpty()) {
			Point p = queue.poll();
			int x = p.x, y = p.y, t = p.t;
			int d = Math.abs(t*x*y)%6;
			if (x % 2 == 0) {
				for (int i = 0; i < 7; i++) {
					int X = x+x0[i], Y = y+y0[i];
					if (X >= -lx && X <= lx && Y >= -ly && Y<= ly && !map[X+pad][Y+pad]) {
						int g = (i == d) ? 0 : 1;
						if (cost[X+pad][Y+pad][(t+1)%6] > p.ig+g) {
							cost[X+pad][Y+pad][(t+1)%6] = p.ig+g;
							queue.add(new Point(X,Y,(t+1)%6,p.ig+g));
						}
					}
				}
			} else {
				for (int i = 0; i < 7; i++) {
					int X = x+x1[i], Y = y+y1[i];
					if (X >= -lx && X <= lx && Y >= -ly && Y<= ly && !map[X+pad][Y+pad]) {
						int g = (i == d) ? 0 : 1;
						if (cost[X+pad][Y+pad][(t+1)%6] > p.ig+g) {
							cost[X+pad][Y+pad][(t+1)%6] = p.ig+g;
							queue.add(new Point(X,Y,(t+1)%6,p.ig+g));
						}
					}
				}
			}
		}

		int res = INF;
		for (int i = 0; i < 6; i++) {	
			res = Math.min(res, cost[gx+pad][gy+pad][i]);
		}
		if (res == INF)
			out.println(-1);
		else
			out.println(res);
	}

	public static void main(String[] args) {
		new Main().run();
	}

}

import java.util.PriorityQueue;
import java.util.Scanner;

public class Main {

	static Scanner sc = new Scanner(System.in);
	static int[] DX = { 0, 1, 1, 0, -1, -1, 0 };
	static int[] DY = { 1, 0, -1, -1, -1, 0, 0 };

	public static void main(String[] arg) {
		int sx = sc.nextInt();
		int sy = sc.nextInt();
		int gx = sc.nextInt();
		int gy = sc.nextInt();
		int N = sc.nextInt();
		int[] ox = new int[N];
		int[] oy = new int[N];
		for (int i = 0; i < N; ++i) {
			ox[i] = sc.nextInt();
			oy[i] = sc.nextInt();
		}
		int LX = sc.nextInt();
		int LY = sc.nextInt();
		sx += LX;
		sy += LY;
		gx += LX;
		gy += LY;
		boolean[][] obst = new boolean[2 * LX + 1][2 * LY + 1];
		for (int i = 0; i < N; ++i) {
			obst[ox[i] + LX][oy[i] + LY] = true;
		}
		boolean[][][] visited = new boolean[6][2 * LX + 1][2 * LY + 1];
		PriorityQueue<State> q = new PriorityQueue<State>();
		q.add(new State(0, sx, sy, 0));
		while (!q.isEmpty()) {
			State cur = q.poll();
			int x = cur.x;
			int y = cur.y;
			int t = cur.t;
			if (visited[t][x][y]) continue;
			visited[t][x][y] = true;
			if (x == gx && y == gy) {
				System.out.println(cur.d);
				return;
			}
			int d = Math.abs((x - LX) * (y - LY) * t) % 6;
			int nt = (t + 1) % 6;
			for (int k = 0; k < 7; ++k) {
				int add = k == d ? 0 : 1;
				int nx = x + DX[k];
				int ny = y + DY[k];
				if (k % 3 != 0 && (x - LX) % 2 != 0) ny++;
				if (0 <= nx && nx <= 2 * LX && 0 <= ny && ny <= 2 * LY && !obst[nx][ny] && !visited[nt][nx][ny]) {
					q.add(new State(cur.d + add, nx, ny, nt));
				}
			}
		}
		System.out.println(-1);
	}

	static class State implements Comparable<State> {
		int d, x, y, t;

		public State(int d, int x, int y, int t) {
			this.d = d;
			this.x = x;
			this.y = y;
			this.t = t;
		}

		public int compareTo(State o) {
			return this.d - o.d;
		}
	}

}

