			public int compare(Pair a,Pair b){
				return a.size-b.size;
			}
		});
		Fenwick dp=new Fenwick(m);
		for(int i=1,j=1;i<=m;i++)
		{
			while(j<=n && list[j].size<i)
			{
				dp.update(list[j].l,list[j].r,1);
				j++;
			}
			for(int k=i;k<=m;k+=i)
				ans.update(i,i,dp.read(k));
		}
		for(int i=1;i<=m;i++)
			out.println(ans.read(i));
	}
	class Pair{
	    int l,r,size;
	    Pair(int a,int b){
	        l=a;
	        r=b;
	        size=r-l+1;
	    }
	}
	class Fenwick
	{
		int tree[],n;
		Fenwick(int n)
		{
			tree=new int[n+1];
			this.n=n;
		}
		int read(int i){
			int ret=0;
			while(i>0){
				ret+=tree[i];
				i-=i&(-i);
			}
			return ret;
		}

		void update(int i,int diff){
			while(i<=n){
				tree[i]+=diff;
				i+=i&(-i);
			}
		}
		void update(int l,int r,int diff)
		{
			update(l,diff);
			update(r+1,-diff);
		}
	}


