						C.addLast(A.poll());
					}

					size = B.size();
					for(int j = 0; j < Math.min(c, size); j++){
						C.addLast(B.poll());
					}
				}

				int index = 0;
				for(int num : C){
					array[index++] = num;
				}
			}


