						set(i, j);
					}
					if(data[i][j] == 'M'){
						bitmap.put(i * h + j, countM++);
					}
				}
			}

			PriorityQueue<State> open = new PriorityQueue<Main.State>();
			open.add(new State(sx, sy, 0, 0));
			int [][][] close = new int[h][w][1 << countM];
			for(int i = 0; i < h; i++){
				for(int j = 0; j < w; j++){
					Arrays.fill(close[i][j], INF);
				}
			}
