	// denom <= a
	// num/denom <= upper
	public static void dfs(long num, long denom, int depth, int start){
		if(depth > n) return;
		double now = (double) num/denom;
		if(Math.abs(now-pq) < EPS){
			count++;
			return;
		}
		if(now > pq) return;
		for(int i=start; (double)(n-depth)/i+now+EPS >= pq && i*denom <= a; i++){
			dfs(num*i + denom, denom*i, depth+1, i);
		}
	}
}

