				pp += vl;
			}
			int lcm = lcm(qq,q);
			int ql = lcm / q;
			int ppx = p * ql;

			int qql = lcm / qq;
			pp *= qql;
			if(ppx < pp) return 0;
			if(ppx == pp) return 1;
		}

		int max = 1;
		int now = 1;
		for(int i = 0; i < id; i++) {
			now *= v[i];
			max = Math.max(v[i], max);
		}
		int ret = 0;
