			v[id] = i;
			ret += solv(id+1,v);
			v[id] = 0;
		}
		return ret;
	}
	static int gcd(int a, int b) {
		if(b > a) {
			return gcd(b,a);
		}
		if(b == 0) return a;
		return gcd(b,a % b);
	}
	static int lcm(int a, int b) {
