        public int m;
        public int mod = 1000000007;

        public void solve(int testNumber, InputReader in, PrintWriter out) {
            n = in.nextInt();
            m = in.nextInt();
            long[][][] dp = new long[2][n + 1][n + 1];
            dp[0][n][0] = 1;
            for (int slots = 1; slots <= m; slots++) {
                int cur = slots % 2, prev = 1 - cur;
