	public static int dfs(int i,int n,int k,ArrayList<Integer> p){
		if(n == 0){
			if(k == 0) return 1;
			else return 0;
		}
		else if(k == 0) return 0;
		if(dp[i][n][k] != -1) return dp[i][n][k];

		int res = 0;
		for(int j=i;p.get(j)<=n;j++){
			res += dfs(j+1,n-p.get(j),k-1,p);
		}
		return dp[i][n][k] = res;
	}

