					if(!f[i] || !f[j] || map[i][j] > M){
						map[i][j] = MAX;
					}
				}
			}

			floyd(map);

			System.out.println(map[A][H]==MAX ? "Help!" : map[A][H]+Math.max(0,map[A][H]-M));
		}
	}

	private static void floyd(int[][] map){
		int n = map.length;

		for(int i=0;i<n;i++){
			for(int j=0;j<n;j++){
				if(map[i][j] == 0) map[i][j] = MAX;
			}
		}

