	Arrays.sort(even,0,n);
	long ta=even[0];
	for(int i=0;i<n;i++){
	    ta=gcd(ta,even[i]);
	}
	long tx0=even[0]/ta,tx1=even[1]/ta;
	long g2=oddmin/tx0/tx1;
	long g=(long)(Math.sqrt(g2));

	//find A=A'/g
	long evenans=ta/g;
	//find all odd ans
	System.out.println(evenans);
	for(int i=0;i<n;i++){
	    if (i!=0)System.out.print(" ");
	    System.out.print(even[i]/evenans);
	}
