//Lupin The 4th
public class Main{

	int n, INF = 1<<29;
	int[] dist, num;
	double[][] dp;
	int[][][] pre;

	double get(int state, int v, int w){
		if(state==(1<<n)-1){
			pre[state][v] = new int[]{-1, -1};
			return 0;
		}
		if(dp[state][v]!=INF)return dp[state][v];
		double min = INF;
		for(int i=0;i<n;i++){
			if(i==v||((state>>i)&1)>0)continue;
			double t = Math.abs(dist[v]-dist[i])/(2000.0/(70+w)) + get(state+(1<<i), i, w+20*num[i]);
			if(t<min){
				min = t;
				pre[state][v] = new int[]{state+(1<<i), i};
			}
		}
		return dp[state][v] = min;
	}

	void run(){
		Scanner sc = new Scanner(System.in);
		n = sc.nextInt();
		int[] ref = new int[n];
