import java.util.Scanner;

public class Main {
	static Scanner sc = new Scanner(System.in);
	static int[] B;

	public static void main(String[] args) {
		int N = sc.nextInt();
		int M = sc.nextInt();
		B = new int[N];
		for (int i = 0; i < N; ++i) {
			B[i] = sc.nextInt();
		}
		int[] target = new int[N];
		int pos = 0;
		int val = 0;
		for (int i = 0; i < M; ++i) {
			int P = sc.nextInt();
			for (int j = 0; j < P; ++j) {
				target[pos++] = val;
			}
			val ^= 1;
		}
		int ans = solve(target);
		for (int i = 0; i < N; ++i) {
			target[i] ^= 1;
		}
		ans = Math.min(ans, solve(target));
		System.out.println(ans);
	}

	static int solve(int[] target) {
		int sum = 0;
		for (int i = 0; i < B.length; ++i) {
			sum += B[i];
			sum -= target[i];
		}
		if (sum != 0) return 999;
		ArrayList<Integer> pos1 = new ArrayList<Integer>();
		ArrayList<Integer> pos2 = new ArrayList<Integer>();
		for (int i = 0; i < B.length; ++i) {
			if (B[i] == 0) pos1.add(i);
			if (target[i] == 0) pos2.add(i);
		}
		int ret = 0;
		for (int i = 0; i < pos1.size(); ++i) {
			ret += Math.abs(pos1.get(i) - pos2.get(i));
		}
		return ret;
	}

}

import java.io.*;
import java.util.*;

public class Main{
	int N;
	int M;
	int[] bits;
	int[] rl;
	public void solve(){
		N = nextInt();
		M = nextInt();
		bits = new int[N];
		for(int i = 0; i < N; i++){
			bits[i] = nextInt();
		}

		rl = new int[M];
		for(int i = 0; i < M; i++){
			rl[i] = nextInt();
		}
		int[] bb = new int[N];
		int idx = 0;
		for(int i = 0; i < M; i++){
			for(int j = 0; j < rl[i]; j++){
				bb[idx++] = i % 2;
			}
		}
		int a = swap(bits, bb);

		idx = 0;
		for(int i = 0; i < M; i++){
			for(int j = 0; j < rl[i]; j++){
				bb[idx++] = (i + 1) % 2;
			}
		}
		int b = swap(bits, bb);
		out.println(Math.min(a, b));
	}

	public int swap(int[] a, int[] b){
		int ans = 0;
		for(int i = 0; i < a.length; i++){
			if(a[i] != b[i]){

				int idx = -1;
				for(int j = i + 1; j < b.length; j++){
					if(a[i] == b[j]){
						idx = j;
						break;
					}
				}
				if(idx == -1) return Integer.MAX_VALUE;
				for(int j = idx; j > i; j--){
					swap(b, j, j - 1);
					ans++;
				}
			}
		}
		return ans;
	}

	public void swap(int[] a, int i, int j){
		int tmp = a[i];
		a[i] = a[j];
		a[j] = tmp;
	}

	private static PrintWriter out;
	public static void main(String[] args){
		out = new PrintWriter(System.out);
		new Main().solve();
		out.flush();
	}



