	public int binarySearch(Check check, int begin, int end){
		int l = begin - 1;
		int r = end;
		while(r - l > 1){
			int m = (r + l) / 2;
			if(check.check(m)){
				r = m;
			}else{
				l = m;
			}
		}
		return r;
	}

	class Check{
		boolean check(int n){
