    public void solve() {
        Scanner scan = new Scanner(new BufferedReader(new InputStreamReader(System.in)));
        int N = scan.nextInt();
        Point[] r = new Point[N];
        for (int i = 0; i < N; i++) {
            Point p = new Point();
            p.x = scan.nextInt();
            p.y = scan.nextInt();
            r[i] = p;
        }
        Point[] b = new Point[N];
        for (int i = 0; i < N; i++) {
            Point p = new Point();
            p.x = scan.nextInt();
            p.y = scan.nextInt();
            b[i] = p;
        }
        Arrays.sort(r, new ReversePointComparator());
        Arrays.sort(b, new PointComparator());
        PointComparator c = new PointComparator();
        int answer = 0;
        boolean[] d_r = new boolean[N];
        Arrays.fill(d_r, false);
        int r_l = -1;
        for (int i = 0; i < N; i++) {
            Point p2 = b[i];
            for (int j = 0; j < N; j++) {
                if (d_r[j]){
                    continue;
                }
                Point p1 = r[j];
                if (p1.x < p2.x && p1.y < p2.y) {
                    d_r[j] = true;
                    answer += 1;
                    break;
                }
            }
        }
        System.out.println(answer);
    }
    class Point {
        int x;
        int y;
    }
    class PointComparator implements Comparator<Point> {
        @Override
        public int compare(Point o1, Point o2) {
            if (o1.x == o2.x) {
                return Integer.compare(o1.y, o2.y);
            }
            return Integer.compare(o1.x, o2.x);
        }
    }
    class ReversePointComparator implements Comparator<Point> {
        @Override
        public int compare(Point o1, Point o2) {
            if (o1.y == o2.y) {
                return -Integer.compare(o1.x, o2.x);
            }
            return -Integer.compare(o1.y, o2.y);
        }
    }
}

