public class Main
{
	static int maxn=100000+100;
	static int n;
	static node[]ns=new node[maxn];
	static int[]bit=new int[maxn];
	static int[]arr=new int[maxn];
	static Scanner scan=new Scanner(System.in);

	public static void main(String[] args)
	{
//		new Thread(new analyze()).start();
		read();
		System.out.println(cal());
	}

	//二分计算答案
	static int cal() {
		int l=0,r=2000000000;//左开右闭
		long half=(n+1)*n/4;
		while(r-l>1) {
			int mid=(l+r)>>1;
			if(f(mid)>half)
				r=mid;
			else
				l=mid;
		}
		return r;	
	}

	//计算中位数小于等于x的区间个数
	static long f(int x) {
		ns[1]=new node(0,1);
		for(int i=2;i<n+2;i++) {
			ns[i]=new node((arr[i-1]>x?1:-1)+ns[i-1].sum,i);
		}
		Arrays.sort(ns,1,n+2);
		//清空bit
		for(int i=1;i<maxn;i++)bit[i]=0;
		long ans=0;
		add(ns[n+1].pos);
		for(int i=n;i>=1;i--){
			ans+=que(ns[i].pos-1);
			add(ns[i].pos);
		}
		return ans;
	}

	//树状数组查询操作
	static int que(int x) {
		int ans=0;
		while(x>0) {
			ans+=bit[x];
			x-=x&-x;
		}
		return ans;
	}

	//树状数组更新操作
	static void add(int x) {
		while(x<maxn) {
			bit[x]++;
			x+=x&-x;
		}
	}

	//读入数据
	static void read() {
		n=scan.nextInt();
		for(int i=1;i<=n;i++) {
			arr[i]=scan.nextInt();
		}
	}
}
