	int sum;
	int pos;
	public node(int s,int p) {
		sum=s;pos=p;
	}
	@Override
	public int compareTo(node arg0)
	{
		return this.sum==arg0.sum?arg0.pos-this.pos:this.sum-arg0.sum;
	}
}

