	    count = 0;
	    solve(num);

	    if(count!=0){
		for(int i=0; i<num.length; i++){
		    if(ans[i]) System.out.print(i+" ");
		}
	    }
	    else System.out.print("0");
	    System.out.println();
	}
    }

    void solve(int[] num){
	/*
	  牌の追加の仕方は9通りなので、全パターン試す
	*/
	for(int k=1; k<10; k++){
	    int[] n = Arrays.copyOf(num, 10);
	    n[k] += 1;
	    /*
	      もし追加したのが5枚目だったら、なかったことにして次へ
	      そうでなければ、成り立っているか確かめる
	    */
	    if(n[k]<5){
		/*
		System.out.println("--- k = "+k+" ---");
		for(int i=0; i<n.length; i++){
		    System.out.println(i+" : "+n[i]);
		}
		*/
		check(n, 0, k, false);
		if(ans[k]) count++;
	    }
	    n[k] -= 1;
	}
    }

    void check(int[] num, int level, int k, boolean f){
	if(level >= num.length){ // 完成の時
	    boolean tf = true;
	    for(int i=0; i<num.length; i++)
		tf = tf && num[i]==0;
	    if(tf) ans[k] = true;
	    return;
	}
	else{ 
	    boolean flag = false;

	    // 1. 刻子ケース
	    if(num[level]>=3){
		flag = true;
		num[level] -= 3;
		if(num[level]==0)
		    check(num, level+1, k, f);
		else
		    check(num, level, k, f);
	    }
	    if(flag){
		num[level] += 3;
		flag = false;
	    }

	    // 2. 雀頭ケース
	    if(num[level]>=2 && !f){
		flag = true;
		f = true;
		num[level] -= 2;
		if(num[level]==0)
		    check(num, level+1, k, f);
		else
		    check(num, level, k, f);
	    }
	    if(flag){
		num[level] += 2;
		flag = false;
	    }

	    // 3. 順子ケース
	    if(level+2<num.length && num[level]>=1 &&
	       num[level+1]>=1 && num[level+2]>=1){
		flag = true;
		num[level] -= 1;
		num[level+1] -= 1;
		num[level+2] -= 1;
		if(num[level]==0)
		    check(num, level+1, k, f);
		else
		    check(num, level, k, f);
	    }
	    if(flag){
		num[level] += 1;
		num[level+1] += 1;
		num[level+2] += 1;
		flag = false;
	    }	

	    check(num, level+1, k, f);
	}
    }
}

public class Main{
  public void run(java.io.InputStream in, java.io.PrintStream out){
    java.util.Scanner sc = new java.util.Scanner(in);
/*answer*/
    int[] count, res;
    char[] ch;
    String str;
    int i, j, k;

    ch = new char[13]; count = new int[9]; res = new int[9];
    for(;sc.hasNext();){
      str = sc.next();
      for(i = 0;i < 9;i++){
        count[i] = 0; res[i] = 0;
      }
      for(i = 0;i < 13;i++){
        ch[i] = str.charAt(i);
        count[ch[i] - '1']++;
      }

      k = 0;
      for(i = 0;i < 9;i++){
        if(count[i] != 4){
          count[i]++;

          for(j = 0;j < 9;j++){
            if(count[j] >= 2){
              count[j] -= 2;
              if(count[j] >= 0 && solve(count, 4)){
                res[k++] = i + 1; count[j] += 2; break;
              }
              count[j] += 2;
            }
          }
          count[i]--;
        }
      }

      for(i = 0;i < k - 1;i++)out.print(res[i] + " ");
      out.println(res[i]);
    }

    sc.close();
  }
  public static void main(String[] args){
    (new Main()).run(System.in, System.out);
  }

  private static boolean solve(int[] count, int t){
    int i, j;
    int[] c2;

    if(t == 0)return true;
    c2 = new int[9];
    for(i = 0;i < 9;i++)c2[i] = count[i];

    for(i = 0;i < 9;i++)if(c2[i] >= 3){
      c2[i] -= 3;
      return solve(c2, t - 1);
    }

    for(i = 0;i < 7;i++){
      if(c2[i] > 0 && c2[i + 1] > 0 && c2[i + 2] > 0){
        c2[i]--; c2[i + 1]--; c2[i + 2]--;
        return solve(c2, t - 1);
      }
    }
    return false;
  }
}

