	    sum += -3 * a + 15 * a + a * 5 * 13;
	    f -= a + 5 * a;

	    //-3*b : ゲーム開始用のコイン
	    //15*b : BARBARBARそろって手に入るコイン
	    //b*3*13 : ボーナスゲーム中のブドウで, 2枚入れて15枚返ってくるやつ
	    sum += -3 * b + 15 * b + b * 3 * 13;
	    f -= b + 3 * b;

	    //-3*c : ゲーム開始用のコイン
	    //7*c : ブドウがそろって手に入るコイン
	    sum += -3 * c + 7 * c;
	    f -= c;

