public class Main {
	static Scanner sc = new Scanner(System.in);
	static int N, M;
	static ArrayList<ArrayList<Integer>> bar = new ArrayList<ArrayList<Integer>>();
	static HashSet<State> used = new HashSet<State>();
	static int[] goal;

	public static void main(String[] args) {
		N = sc.nextInt();
		M = sc.nextInt();
		goal = new int[N];
		for (int i = 0; i < N - 1; ++i) {
