		}
		for (int i = 0; i < M; ++i) {
			int a = sc.nextInt() - 1;
			bar.get(a).add(i);
			int tmp = goal[a];
			goal[a] = goal[a + 1];
			goal[a + 1] = tmp;
		}
		HashSet<State> cur = new HashSet<State>();
		cur.add(new State());
		for (int i = 0;; ++i) {
			HashSet<State> next = new HashSet<State>();
			for (State s : cur) {
				if (s.goal()) {
					System.out.println(i);
					return;
				}
				s.trans(next, 0, 0);
			}
			cur = next;
		}
	}

	static class State {
		int[] count;
		int[] match;

		State() {
			count = new int[N - 1];
			match = new int[N];
			for (int i = 0; i < N; ++i) {
				match[i] = i;
			}
		}

		State(State o) {
			count = o.count.clone();
			match = o.match.clone();
		}

		public int hashCode() {
			return Arrays.hashCode(count) * 31 ^ Arrays.hashCode(match);
		}

		public boolean equals(Object o) {
			if (this == o) return true;
			if (getClass() != o.getClass()) return false;
			return Arrays.equals(count, ((State) o).count) && Arrays.equals(match, ((State) o).match);
		}

		void trans(HashSet<State> next, int use, int pos) {
			if (pos == N - 1) {
				if (use == 0) return;
				State n = new State(this);
				for (int i = 0; i < N - 1; ++i) {
					if ((use & (1 << i)) != 0) {
						n.count[i]++;
						int tmp = n.match[i];
						n.match[i] = n.match[i + 1];
						n.match[i + 1] = tmp;
					}
				}
				if (!used.contains(n)) {
					used.add(n);
					next.add(n);
				}
				return;
			}
			trans(next, use, pos + 1);
			if (canUse(use, pos)) {
				trans(next, use | (1 << pos), pos + 1);
			}
		}

		boolean canUse(int use, int pos) {
			if (count[pos] == bar.get(pos).size()) return false;
			if (pos > 0 && (use & (1 << (pos - 1))) != 0) return false;
			//			if (pos > 0) {
