		int M = sc.nextInt();
		int S = sc.nextInt();
		int T = sc.nextInt();
		--S;
		--T;
		ArrayList<Edge>[] g = new ArrayList[N];
		for (int i = 0; i < N; ++i) {
			g[i] = new ArrayList();
		}
		long[][] es = new long[M][];
		for (int i = 0; i < M; ++i) {
			int u = sc.nextInt();
			int v = sc.nextInt();
			long d = sc.nextLong();
			--u;
			--v;
			g[u].add(new Edge(u, v, d));
			g[v].add(new Edge(v, u, d));
