					&& 2 * a[0][u] < DIST && DIST < 2 * (a[0][u] + d)) {
				long x = a[1][u] * b[1][v] % MOD;
				x = x * x % MOD;
				sub = (sub + x) % MOD;
			}
			if (DIST == a[0][v] + d + b[0][u] && 2 * a[0][v] < DIST
					&& DIST < 2 * (a[0][v] + d)) {
				long x = a[1][v] * b[1][u] % MOD;
				x = x * x % MOD;
				sub = (sub + x) % MOD;
