import java.util.*;

class Node {
  Node parent;
  int id;
  int rank;

  Node(int id) {
    this.parent = null;
    this.id = id;
    this.rank = 0;
  }

  public Node getRoot() {
    if (parent == null) {
      return this;
    }
    Node root = parent.getRoot();
    parent = root;
    return root;
  }

  public long getRootId() {
    return getRoot().id;
  }

  public static void merge(Node a, Node b) {
    Node aRoot = a.getRoot();
    Node bRoot = b.getRoot();

    if (aRoot.rank > bRoot.rank) {
      bRoot.parent = aRoot;
    } else if (aRoot.rank < bRoot.rank) {
      aRoot.parent = bRoot;
    } else if (aRoot != bRoot) {
      aRoot.parent = bRoot;
      bRoot.rank = bRoot.rank + 1;
    }
  }
}

