public class Main {

	static Scanner sc = new Scanner(System.in);
	static int[] v;

	static int solve(int pos, int c) {
		int tmp = v[pos];
		v[pos] = c;
		int up = pos;
		int dp = pos;
		int count = 0;
		while (0 <= up && dp < v.length && v[up] == v[dp]) {
			int color = v[up];
			int num = up == dp ? -1 : 0;
			while (0 <= up && v[up] == color) {
				--up;
				++num;
			}
			while (dp < v.length && v[dp] == color) {
				++dp;
				++num;
			}
			if (num < 4) break;
			count += num;
		}
		v[pos] = tmp;
		return count;
	}

	public static void main(String[] args) {
		while (true) {
			int N = sc.nextInt();
			if (N == 0) break;
			v = new int[N];
