				v[i] = sc.next().charAt(0) - '0';
			}
			int ans = 0;
			for (int i = 0; i < N; ++i) {
				int u = i == 0 ? -1 : v[i - 1];
				int d = i == N - 1 ? -1 : v[i + 1];
				if (u != -1 && u != v[i]) {
					ans = Math.max(ans, solve(i, u));
				}
				if (d != -1 && d != v[i] && u != d) {
					ans = Math.max(ans, solve(i, d));
				}
			}
			System.out.println(N - ans);
		}
	}
