			if(i == maxindex) continue;

			if(i < maxindex)
				list[i] = W[i];
			else {
				list[i-1] = W[i];
			}
		}

		int totalwrite = calc(list, free);

		System.out.println(maxread*2+sumwrite-totalwrite);
	}

	static public void main(String[] args)
