class Match {
	class Team {
		int loseCnt = 0;
		List<Integer> winTo = new ArrayList<Integer>();
	}

	Team[] team;
	boolean vague = false;

	public Match(int n) {
		team = new Team[n + 1];
		for (int i = 1; i < team.length; i++)
			team[i] = new Team();
	}

	public int getDefined() {
		if (vague)
			return 1;
		else
			return 0;
	}

	public int getTopOrder() {
		int top = 0;
		for (int i = 1; i < team.length; i++) {
			if (team[i].loseCnt == 0) {
				if (top != 0) {
					vague = true;
					break;
				}
				top = i;
				team[i].loseCnt = -1;
				if (vague)
					break;
			}
		}
		for (int i = 0; i < team[top].winTo.size(); i++)
			team[team[top].winTo.get(i)].loseCnt--;
		return top;
	}

	public void add(int winner, int loser) {
		team[loser].loseCnt++;
		team[winner].winTo.add(loser);
	}
}

