import static java.lang.Integer.parseInt;

public class Main {

	@SuppressWarnings("unchecked")
	public static void main(String[] args) throws IOException {

		BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
		String line;

		int n = parseInt(br.readLine());
		int m = parseInt(br.readLine());
		List<Integer>[] indeg = new List[n + 1];
		List<Integer>[] outdeg = new List[n + 1];
		List<Integer> idx = new ArrayList<Integer>();
		Deque<Integer> rank = new ArrayDeque<Integer>();
		boolean alt = false;

		for (int i = 1; i <= n; i++) {
			indeg[i] = new ArrayList<Integer>();
			outdeg[i] = new ArrayList<Integer>();
			idx.add(i);
		}
		for (int i = 0; i < m; i++) {
			line = br.readLine();
			int a = parseInt(line.substring(0, line.indexOf(' ')));
			int b = parseInt(line.substring(line.indexOf(' ') + 1));
			indeg[b].add(a);
			outdeg[a].add(b);
		}
		//solve
		while (!idx.isEmpty()) {
			if (!alt) {
				int winners = 0;
				for (Integer winner : idx) {
					if (indeg[winner].size() == 0) winners++;
					if (winners > 1) {
						alt = true;
						break;
					}
				}
			}
			for (Integer winner : idx) {
				if (indeg[winner].size() == 0) {
					rank.add(winner);
					for (int loser : outdeg[winner]) {
						indeg[loser].remove(winner);
					}
					break;
				}
			}
			idx.remove(rank.peekLast());
		}
		rank.add(alt ? 1 : 0);
		for (int i : rank) {
			System.out.println(i);
		}
	}
}

import java.util.LinkedList;
import java.util.Scanner;

public class Main {

	public static final int unvisited = 0;
	public static final int visiting = 1;
	public static final int visited = 2;

	public static boolean dfs(int node, boolean[][] adj, int[] state, LinkedList<Integer> list){
	    state[node] = visiting;

	    for(int i = 0; i < adj.length; i++){
	        if(!adj[node][i]){ continue; }
	        else if(state[i] == unvisited){
	            if(!dfs(i, adj, state, list)){ //
	                state[node] = visited; return false;
	            }
	        }else if(state[i] == visiting){ //cycle!
	            return false;
	        }
	    }

	    state[node] = visited;
	    list.addFirst(node);
	    return true;
	}

	public static boolean topological_sort(boolean[][] adj, LinkedList<Integer> list){
	    int[] state = new int[adj.length];
	    for(int i = 0; i < adj.length; i++){
	        state[i] = unvisited;
	    }
	    for(int i = 0; i < adj.length; i++){
	        if(state[i] == unvisited){
	            if(!dfs(i, adj, state, list)){
	                return false;
	            }
	        }
	    }
	    return true;
	}


	public static class UnionFind{
	    int[] par; // 

	    public UnionFind(int n){
	        par = new int[n];
	        for(int i = 0; i < n; i++){ par[i] = -1; }
	    }

	    public int find(int x){
	        if(par[x] < 0){
	            return x;
	        }else{
	            return par[x] = find(par[x]);
	        }
	    }

	    public boolean union(int x, int y){
	        x = find(x);
	        y = find(y);

	        if(x != y){
	            if(par[y] < par[x]) {  // 多い方が根になるようにスワップする.
	                int tmp = x; x = y; y = tmp;
	            }
	            par[x] += par[y];
	            par[y] = x;
	            return true;
	        }else{
	            return false;
	        }
	    }

	    public boolean same(int x, int y){
	        return find(x) == find(y);
	    }

	    public int size(int x){
	        return -par[find(x)];
	    }
	}

	public static void main(String[] args) {
