				sx = scanner.nextInt() - 1;
				sy = scanner.nextInt() - 1;
				int[][] m = new int[h][w];
				for (int j = 0; j < h; j++)
					for (int k = 0; k < w; k++)
						m[j][k] = scanner.nextInt();
				slove(m, i);
			}
			int res = 1 << 30;
			for (int i = 0; i <= r; i++) {
				res = Math.min(res, map[0][i] + map[1][r - i]);
			}
			System.out.println(res);
		}
	}

	private void slove(int[][] m, int i) {
		boolean[][] b = new boolean[h][w];
		int id = 1;
		int l = -1;
		b[sy][sx] = true;
		int a = h * w - 1;
		PriorityQueue<Point> pq = new PriorityQueue<Point>();
		pq.offer(new Point(m[sy][sx], sy, sx));
		while (!pq.isEmpty()) {
			Point point = pq.poll();
			l = Math.max(l, point.k);
			map[i][id++] = l;
			if(a==0){
				continue;
			}
			for (int[] mo : move) {
				int ny = point.y + mo[0];
				int nx = point.x + mo[1];
				if (!isOK(ny, nx))
					continue;
				if (b[ny][nx])
					continue;
				b[ny][nx] = true;
				a--;
				pq.offer(new Point(m[ny][nx], ny, nx));
			}
		}
	}

	private boolean isOK(int ny, int nx) {
		if (0 <= ny && ny < h && 0 <= nx && nx < w)
			return true;
		return false;
	}
	int r, w, h, sx, sy;
	int[][] map;
	int[][] move = { { -1, 0 }, { 0, -1 }, { 0, 1 }, { 1, 0 } };

	class Point implements Comparable<Point> {
