				sb.append(((out / 1000) > 1 ? (out / 1000) : "") + "m");
				out = out % 1000;
			}else if((out / 100) != 0){
				sb.append(((out / 100) > 1 ? (out / 100) : "") + "c");
				out = out % 100;
			}else if((out / 10) != 0){
				sb.append(((out / 10) > 1 ? (out / 10) : "") + "x");
				out = out % 10;
			}else if(out != 0){
				sb.append((out > 1 ? out : "") + "i");
				out = 0;
			}
		}

		return sb.toString();
