import array


def num_string_to_array(num_string):
    return array.array("B", map(int, num_string))


def num_array_to_string(num_array):
    return "".join(map(str, num_array))


def solve(n, x, d):
    answer = x[:]
    rest_distance = d
    for i in range(n):
        if rest_distance <= 0:
            return answer
        elif answer[i] == 0:
            answer[i] = 1
            rest_distance -= 1
    for j in range(n)[::-1]:
        if rest_distance <= 0:
            return answer
        elif answer[j] == 1 and answer[j] == x[j]:
            answer[j] = 0
            rest_distance -= 1
    return answer


def main():
    n = int(input())
    x = num_string_to_array(input())
    d = int(input())
    answer = num_array_to_string(solve(n, x[:], d))
    print(answer)


if __name__ == '__main__':
