					double arg = Math.abs(Math.acos((dx1 * dx2 + dy1 * dy2) / dist[i][j] / dist[j][k])) * 180 / Math.PI;
					ok[i][j][k] = arg <= theta;
				}
			}
		}
		double[][][] dp = new double[2][N][N];
		for (double[][] a : dp) {
			for (double[] aa : a) {
