			}
		}
		boolean any = false;
		for (int i = 1; i < N; ++i) {
			if (dist[0][i] <= R) {
				any = true;
				dp[0][0][i] = R - dist[0][i];
			}
		}
		if (!any) {
			System.out.println(0);
			return;
		}
		int t = 1;
		for (int turn = 1;; ++turn) {
			for (double[] a : dp[t]) {
				Arrays.fill(a, -1);
			}
			boolean update = false;
			for (int i = 0; i < N; ++i) {
				for (int j = 0; j < N; ++j) {
					if (dp[1 - t][i][j] < 0) continue;
					for (int k = 0; k < N; ++k) {
						if (!ok[i][j][k] || dp[1 - t][i][j] < dist[j][k]) continue;
						update = true;
						dp[t][j][k] = Math.max(dp[t][j][k], dp[1 - t][i][j] - dist[j][k]);
