                    //System.out.println(sum - x + " " + sum);
                    a -= sum - x;
                    ans += sum - x;
                    sum = x;
                } else {
                    //System.out.println(0 + " " + sum);
                }
                sum -= prev;
                prev = a;
            }
            out.println(ans);
        }

