	private void solve(int ind) {
		StringBuilder sb = new StringBuilder(data[ind]);
		int len = sb.length();
		//delete
		for(int i = 0; i < len; i++){
			char c = sb.charAt(i);
			sb.deleteCharAt(i);
			data2.get(ind).add(sb.toString());
			sb.insert(i, c);
		}

		//insert
		for(int i = 0; i <= len; i++){
			for(int j = 'a'; j <= 'z'; j++){
				sb.insert(i, (char)j);
				data2.get(ind).add(sb.toString());
				sb.deleteCharAt(i);
			}
		}
		//replace
		for(int i = 0; i < len; i++){
			for(int j = 'a'; j <= 'z'; j++){
				char c = sb.charAt(i);
				sb.setCharAt(i, (char)j);
				data2.get(ind).add(sb.toString());
				sb.setCharAt(i, c);
			}
		}

		//swap
		for(int i = 1; i < len; i++){
			swap(sb, i-1, i);
			data2.get(ind).add(sb.toString());
			swap(sb, i-1, i);
		}
	}

	private void swap(StringBuilder sb, int i, int j) {
		char c = sb.charAt(i);
		sb.setCharAt(i, sb.charAt(j));
		sb.setCharAt(j, c);
	}

