    int rotate(char c, int d) {
        return ((c - 'a') + d) % 26 + 'a';
    }
    void decipher(int ai, int bi) {
        int d = Math.abs(ai - bi);
        message[ai] = (char)rotate(message[ai], d);
        message[bi] = (char)rotate(message[bi], d);
        char p = message[ai];
        char q = message[bi];
        message[ai] = q;
        message[bi] = p;
    }
    void run() {
        while (init()) {
            for (int i = a.length-1; i >= 0; i--) {
                decipher(a[i], b[i]);
            }
            System.out.println(message);
        }
    }
}

