			for (int i = 0; i < n; i++) {
				int root = i;
				int[] used = new int[n];
				Arrays.fill(used, -1);
				Deque<Integer> st = new ArrayDeque<>();
				st.push(root);
				used[root] = 0;
				int cnt = 0;
				while (!st.isEmpty()) {
					int e = st.pop();

					for (int ne : edges.get(e)) {
						if (used[ne] >= 0) {
							continue;
						}
						st.push(ne);
						used[ne] = used[e] + 1;
						if (used[ne] > k / 2) {
							cnt++;
						}
					}
				}
				ret = Math.min(ret, cnt);
			}
		} else {
			for (int i = 0; i < n - 1; i++) {
				int[] used = new int[n];
				Arrays.fill(used, -1);
				Deque<Integer> st = new ArrayDeque<>();
				st.push(a[i]);
				st.push(b[i]);
				used[a[i]] = 0;
				used[b[i]] = 0;
				int cnt = 0;
				while (!st.isEmpty()) {
					int e = st.pop();

					for (int ne : edges.get(e)) {
						if (used[ne] >= 0) {
							continue;
						}
						st.push(ne);
						used[ne] = used[e] + 1;
						if (used[ne] > k / 2) {
							cnt++;
						}
					}
				}
				ret = Math.min(ret, cnt);
			}
		}

		pr.println(ret);

		pr.close();
		sc.close();
	}

