		}
	}

	//SHAKYO
	private void addEdge(int from, int to, int cap, int cost){
		G.get(from).add(new Edge(to, cap, cost, G.get(to).size()));
		G.get(to).add(new Edge(from, 0, -cost, G.get(from).size() - 1));
	}

	//SHAKYO
	private int minCostFlow(int s, int t, int f) {
		int V = G.size();
		int [] dist = new int[V];
		int [] prevv = new int[V];
		int [] preve = new int[V];

		int res = 0;
		while(f > 0){
			//ベルマン
