		int min[] = new int[N];
		min[0] = A[0];
		for (int i = 1; i < N; i++) {
			if (A[i] < min[i-1]) {
				min[i] = A[i];
			} else {
				min[i] = min[i-1];
			}
		}
		// i 以降のAiの最大値
		int max[] = new int[N];
		max[N-1] = A[N-1];
		for (int i = N - 2; i >=0; i--) {
			if(A[i] > max[i + 1]) {
				max[i] = A[i];
			} else {
				max[i] = max[i + 1];
			}
		}
		// 最大の価格差
		int maxgap = 0;
		for (int i = 0; i < N; i++) {
