	static int[] pow(int[] m, long K) {
		int[] ans = new int[m.length];
		for(int i=0; i<ans.length; i++)
			ans[i] = i;

		while(K>0) {
			if((K&1)!=0) {
				ans = mul(ans, m);
			}
			m = mul(m, m);

			K>>=1;
		}

		return ans;
	}

	static int[] mul(int[] a, int[] b) {
		int[] ans = new int[a.length];
		for(int i=0; i<ans.length; i++)
			ans[i] = a[b[i]];
		return ans;
	}
