			if (f.i == f.n.child.size()) {
				ret = f.t + f.n.v;
				continue;
			}
			stack.add(new Frame(f.n, f.i + 1, f.t));
			stack.add(new Frame(f.n.child.get(f.i), 0, 0));
		}
		System.out.println(ret);
	}

