        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        for (long i = 1; i <= 3500; i++) {
            for (long j = i; j <= 3500; j++) {
                long k = lcm(i, j);
                double a = k/i;
                double b = k/j;
                if (((a+b+1)/k)*N == 4.0) {
                    System.out.println(i + " " + j + " " + k);
                    return;
                }
            }
        }
    }

    private static long gcd(long a, long b) {
        while (b > 0) {
            long temp = b;
            b = a % b; // % is remainder
            a = temp;
        }
        return a;
    }


    private static long lcm(long a, long b) {
        return a * (b / gcd(a, b));
    }
}

