        public void solve(int testNumber, Scanner in, PrintWriter out) {
            int N = in.nextInt();
            int M = in.nextInt();
            String[] d = new String[M];
            for (int i = 0; i < M; i++) {
                d[i] = in.next();
            }
            int[] wsum = new int[N + 1];
            int[] esum = new int[N + 1];
            boolean west = false, east = false;
            for (int i = 0; i < M; i++) {
                for (int j = 0; j < N; j++) {
                    if (d[i].charAt(j) == 'E') {
                        esum[j + 1]++;
                        east = true;
                    } else {
                        wsum[j + 1]++;
                        west = true;
                    }
                }
            }
            if (!east) {
                out.println(N + " " + (N + 1));
                return;
            }
            if (!west) {
                out.println(0 + " " + 1);
                return;
            }
            for (int i = 0; i < N; i++) {
                wsum[i + 1] += wsum[i];
                esum[i + 1] += esum[i];
