			s--;
			d--;
			int[][] e = new int[n][n];
			for(int[]ee:e)Arrays.fill(ee, 1<<28);
			while(m--!=0){
				int a = sc.nextInt()-1;
				int b = sc.nextInt()-1;
				int cos = sc.nextInt();
